#include <latch>
#include <thread>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::latch latch{2};
    assert(std::latch::max() >= 2);
    assert(!latch.try_wait());
    latch.count_down();
    std::jthread worker([&] { latch.arrive_and_wait(); });
    latch.wait();
    assert(latch.try_wait());
}
